def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the repeated color strip and read its colors in left-to-right order.
    palette = None
    for r in range(h):
        for k in range(2, h - r + 1):
            if all(grid[r + i] == grid[r] for i in range(k)):
                vals = [v for v in grid[r] if v != 0]
                if len(vals) >= 2 and len(set(vals)) == len(vals):
                    palette = vals
                    break
        if palette:
            break

    # Find connected components of color 1; the main silhouette is the largest.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    shape = max(components, key=len)
    r0 = min(r for r, c in shape)
    r1 = max(r for r, c in shape)
    c0 = min(c for r, c in shape)
    c1 = max(c for r, c in shape)
    pattern = {(r - r0, c - c0) for r, c in shape}
    sh, sw = r1 - r0 + 1, c1 - c0 + 1

    # Stack one silhouette per palette color, preserving the location of color 1.
    idx = palette.index(1)
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        top = r0 + (i - idx) * sh
        for dy, dx in pattern:
            y, x = top + dy, c0 + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out
